    16	use constant SOURCE_LIST_MAX_BYTES => 64 * 1024;
    17	
    18	sub _fatal {
    19	    my ($message) = @_;
    20	    die "whisper-record-toggle: $message\n";
    21	}
    22	
    23	sub _command_status {
    24	    my (@command) = @_;
    25	    my $status = system { $command[0] } @command;
    26	    return if $status == 0;
    27	    my $detail = $status == -1 ? "exec error: $!" : "exit status " . ($status >> 8);
    28	    _fatal("command failed: $detail");
    29	}
    30	
    31	sub _command_output_quietly {
    32	    my ($self, @command) = @_;
    33	    my $pid = open my $fh, '-|';
    34	    defined $pid or _fatal("cannot fork command: $!");
    35	    if ($pid == 0) {
    36	        open STDERR, '>', '/dev/null' or _exit(125);
    37	        exec { $command[0] } @command or _exit(127);
    38	    }
    39	
    40	    my $output = q{};
    41	    while (1) {
    42	        my $remaining = SOURCE_LIST_MAX_BYTES - length $output;
    43	        if ($remaining <= 0) {
    44	            close $fh;
    45	            return (0, q{});
    46	        }
    47	        my $read_size = $remaining < 8192 ? $remaining : 8192;
    48	        my $read = read($fh, my $chunk, $read_size);
    49	        if (!defined $read) {
    50	            close $fh;
    51	            return (0, q{});
    52	        }
    53	        last if $read == 0;
    54	        $output .= $chunk;
    55	    }
    56	
    57	    my $closed = close $fh;
    58	    return ($closed && $? == 0, $output);
    59	}
    60	
    61	sub _source_ids_from_list {
    62	    my ($self, $output) = @_;
    63	    my ($default_source, @source_ids);
    64	
    65	    # wpctl list emits tab-separated records. Keep the marked default first for
    66	    # callers that only need one source while retaining every input for the
    67	    # login-time privacy default.
    68	    for my $line (split /\n/, $output) {
    69	        $line =~ s/\r\z//;
    70	        my ($id, $name, $media_class, @markers) = split /\t/, $line, -1;
    71	        next if !defined($id) || !defined($name) || !defined($media_class);
    72	        next if $id !~ /\A[1-9][0-9]*\z/;
    73	        next if $media_class !~ m{\AAudio/Source(?:/|\z)};
    74	        push @source_ids, $id;
    75	        $default_source = $id if grep { $_ eq '*' } @markers;
    76	    }
    77	
    78	    return @source_ids if !defined $default_source;
    79	    return (
    80	        $default_source,
    81	        grep { $_ ne $default_source } @source_ids,
    82	    );
    83	}
    84	
    85	sub _available_source_ids {
    86	    my ($self, $wpctl) = @_;
    87	    my ($listed, $output) = $self->_command_output_quietly(
    88	        $wpctl, 'list', 'audio', 'sources',
    89	    );
    90	    return if !$listed;
    91	
    92	    return $self->_source_ids_from_list($output);
    93	}
    94	
    95	sub _wait_for_sources {
    96	    my ($self, $wpctl) = @_;
    97	    my $attempts = $self->default_source_attempts();
    98	    $attempts =~ /\A[1-9][0-9]*\z/ or _fatal('invalid default source attempt count');
    99	    my $retry_seconds = $self->default_source_retry_seconds();
   100	    defined $retry_seconds && $retry_seconds =~ /\A(?:0|[1-9][0-9]*)(?:\.[0-9]+)?\z/
   101	        or _fatal('invalid default source retry interval');
   102	
   103	    for my $attempt (1 .. $attempts) {
   104	        my @source_ids = $self->_available_source_ids($wpctl);
   105	        return @source_ids if @source_ids;
   106	        sleep $retry_seconds if $attempt < $attempts;
   107	    }
   108	    return;
   109	}
   110	
   111	sub _wait_for_source {
   112	    my ($self, $wpctl) = @_;
   113	    my @source_ids = $self->_wait_for_sources($wpctl);
   114	    return $source_ids[0];
   115	}
   116	
   117	sub set_default_source_muted {
   118	    my ($self, $muted) = @_;
   119	    $muted == 0 || $muted == 1 or _fatal('invalid microphone mute state');
   120	    my $wpctl = $self->wpctl_binary();
   121	    -x $wpctl && -f $wpctl or _fatal('wpctl is unavailable');
   122	    my $source_id = $self->_wait_for_source($wpctl);
   123	    defined $source_id
   124	        or _fatal('no usable audio capture source became available');
   125	    _command_status($wpctl, 'set-mute', $source_id, "$muted");
   126	    return 1;
   127	}
   128	
   129	sub set_available_sources_muted {
   130	    my ($self, $muted) = @_;
   131	    $muted == 0 || $muted == 1 or _fatal('invalid microphone mute state');
   132	    my $wpctl = $self->wpctl_binary();
   133	    -x $wpctl && -f $wpctl or _fatal('wpctl is unavailable');
   134	    my @source_ids = $self->_wait_for_sources($wpctl);
   135	    @source_ids
   136	        or _fatal('no usable audio capture source became available');
   137	
   138	    # Do not call wpctl set-default here: muting capture endpoints must not
   139	    # replace the source selected by the user or WirePlumber policy.
   140	    for my $source_id (@source_ids) {
   141	        _command_status($wpctl, 'set-mute', $source_id, "$muted");
   142	    }
   143	    return scalar @source_ids;
   144	}
   145	
   146	sub record {
   147	    my ($self, $destination) = @_;
   148	    my $binary = $ENV{WHISPER_PW_RECORD_BIN} // '/usr/bin/pw-record';
   149	    -x $binary && -f $binary && $binary =~ m{\A/}
   150	        or _fatal('pw-record is unavailable');
   151	    exec { $binary } $binary, '--rate=16000', '--channels=1', '--format=s16', $destination
   152	        or _fatal("cannot exec pw-record: $!");
   153	}
