    18	sub log_msg {
    19	    my ($level, $message) = @_;
    20	    $level = exists $PRIORITY{$level} ? $level : 'error';
    21	    $message = q{} if !defined $message;
    22	    $message =~ s/[\r\n]+/ /g;
    23	    $message =~ s/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/?/g;
    24	    $message = substr($message, 0, 2048);
    25	
    26	    return if !eval {
    27	        openlog('whisper-record-toggle', 'pid,nowait', LOG_USER);
    28	        syslog($PRIORITY{$level}, '%s', $message);
    29	        closelog();
    30	        1;
    31	    };
    32	}
