    24	sub _recorder {
    25	    my ($self) = @_;
    26	    return WhisperMode::Recorder->new(
    27	        artifacts => $self->artifacts(), audio => $self->audio(),
    28	        state => $self->state(), systemd => $self->systemd(),
    29	    );
    30	}
    31	
    32	sub _memory {
    33	    my ($self) = @_;
    34	    return WhisperMode::Memory->new(config => $self->config(), systemd => $self->systemd());
    35	}
    36	
    37	sub run {
    38	    my ($self, $action) = @_;
    39	    if ($action eq 'server-enabled') {
    40	        $self->_memory()->enabled() or die "whisper-record-toggle: WHISPER_PERSISTENT_MEM is disabled\n";
    41	        return 0;
    42	    }
    43	    if ($action eq 'server') {
    44	        $self->_memory()->run_server();
    45	        return 0;
    46	    }
    47	    if ($action eq 'record-worker') {
    48	        my $lock = $self->state()->lock(0, 0);
    49	        $self->_recorder()->record_worker();
    50	        return 0;
    51	    }
    52	    if ($action eq 'transcribe') {
    53	        my $lock = $self->state()->lock(0, 0);
    54	        WhisperMode::Transcriber->new(
    55	            artifacts => $self->artifacts(), config => $self->config(),
    56	            memory => $self->_memory(), state => $self->state(),
    57	        )->transcribe_pending();
    58	        return 0;
    59	    }
    60	    if ($action eq 'mute-default-source') {
    61	        my $lock = $self->state()->lock(0, 1);
    62	        return 0 if !$lock;
    63	        return 0 if $self->systemd()->is_active($self->systemd()->record_service());
    64	        my $muted = $self->audio()->set_default_source_muted(1);
    65	        $muted or die "whisper-record-toggle: no usable audio capture source became available\n";
    66	        return 0;
    67	    }
    68	
    69	    my $lock = $self->state()->lock(0, 0);
    70	    my $recorder = $self->_recorder();
    71	    my $pending = $self->state()->read();
    72	    my $transcribe = 0;
    73	    if ($action eq 'toggle') {
    74	        if ($self->systemd()->is_active($self->systemd()->record_service()) || $pending) {
    75	            $transcribe = defined $recorder->stop();
    76	        } else {
    77	            $recorder->start();
    78	        }
    79	    } elsif ($action eq 'start') {
    80	        $recorder->start();
    81	    } elsif ($action eq 'stop') {
    82	        $transcribe = defined $recorder->stop();
    83	    } else {
    84	        die "whisper-record-toggle: unsupported action: $action\n";
    85	    }
    86	    undef $lock;
    87	    $self->systemd()->start_transcription() if $transcribe;
    88	    return 0;
    89	}
