    18	sub _fatal {
    19	    my ($message) = @_;
    20	    die "whisper-record-toggle: $message\n";
    21	}
    22	
    23	sub _normalize {
    24	    my ($text) = @_;
    25	    $text //= q{};
    26	    $text =~ s/[\p{Cc}\p{Cf}]+/ /gu;
    27	    $text =~ s/\s+/ /gu;
    28	    $text =~ s/\A\s+|\s+\z//gu;
    29	    return $text;
    30	}
    31	
    32	sub _text_from_json {
    33	    my ($data) = @_;
    34	    my @parts;
    35	    for my $key (qw(transcription segments)) {
    36	        if (ref $data->{$key} eq 'ARRAY') {
    37	            push @parts, map { ref $_ eq 'HASH' && defined $_->{text} ? $_->{text} : () } @{ $data->{$key} };
    38	            last;
    39	        }
    40	    }
    41	    push @parts, $data->{text} if !@parts && defined $data->{text};
    42	    push @parts, $data->{result}{text} if !@parts && ref($data->{result}) eq 'HASH' && defined $data->{result}{text};
    43	    return _normalize(join q{ }, @parts);
    44	}
    45	
    46	sub transcribe_pending {
    47	    my ($self) = @_;
    48	    my $recording = $self->state()->read() or return;
    49	    my $wav = $self->artifacts()->validate_wav($recording);
    50	    -f $wav && !-l $wav && -s $wav > 44
    51	        or _fatal('recorded WAV is missing or too small to transcribe');
    52	
    53	    my ($fh, $json) = tempfile('.whisper-transcript.XXXXXX', DIR => $self->state()->runtime_directory(), UNLINK => 0);
    54	    close $fh or _fatal("cannot create transient transcription output: $!");
    55	    if ($self->config()->persistent_memory_enabled()) {
    56	        $self->memory()->transcribe($wav, $json);
    57	    } else {
    58	        my $prefix = $json;
    59	        $prefix =~ s/\.XXXXXX\z//;
    60	        my @command = (
    61	            $self->config()->value('WHISPER_CLI'),
    62	            '--model', $self->config()->value('WHISPER_MODEL'),
    63	            '--file', $wav, '--threads', $self->config()->thread_count(),
    64	            '--output-json', '--no-timestamps', '--output-file', $prefix,
    65	        );
    66	        my $status = system { $command[0] } @command;
    67	        $status == 0 or _fatal('whisper-cli transcription failed');
    68	        unlink $json if -e $json;
    69	        $json = "$prefix.json";
    70	    }
    71	    my $data = $self->artifacts()->read_json($json, 8 * 1024 * 1024, 'Whisper transcription output');
    72	    unlink $json or _fatal("cannot remove transient Whisper output: $!");
    73	    my $text = _text_from_json($data);
    74	    $self->artifacts()->store_transcript($recording->{stem}, $text);
    75	    $self->artifacts()->append_task($recording->{stem}, $text);
    76	    my $paths = $self->artifacts()->paths();
    77	    $self->artifacts()->prune($paths->{audio}, 'wav');
    78	    $self->artifacts()->prune($paths->{transcribed}, 'json');
    79	    $self->state()->clear();
    80	    log_msg('info', "transcribed Whisper recording $recording->{stem}");
    81	}
