   grep -Fqx 'list audio sources' "$TMP_DIR/wpctl.log" &&
   grep -Fqx 'set-default 42' "$TMP_DIR/wpctl.log" &&
   grep -Fqx 'set-mute 42 1' "$TMP_DIR/wpctl.log"; then
  pass "Whisper avoids WirePlumber's invalid default token and mutes a validated numeric source"
else
  fail "Whisper avoids WirePlumber's invalid default token and mutes a validated numeric source"
fi

cat >"$TMP_DIR/no-default-source.pl" <<'EOF'
use strict;
use warnings;

use WhisperMode::Audio;

my $audio = WhisperMode::Audio->new(
    default_source_attempts      => 2,
    default_source_retry_seconds => 0,
