apparmor_mode_config_has_profile() {
  profile_name=$1
  mode_config=$2

  awk -v expected_profile="$profile_name" '
    /^[[:space:]]*(#|$)/ { next }
    NF == 4 && $3 == expected_profile { matches++ }
    END { exit(matches == 1 ? 0 : 1) }
  ' "$mode_config"
}

