     >"$TMP_DIR/digital-assets-menu-catalog" 2>&1 &&
   grep -Fq 'docx-to-pdf' "$TMP_DIR/digital-assets-menu-catalog" &&
   grep -Fq 'pdf-to-png' "$TMP_DIR/digital-assets-menu-catalog"; then
  digital_assets_catalog_cli_ok=true
