from pathlib import Path
import re
placeholders={
'__INSTALLER_FILE_BOOTPROFILE_APPLY__':'/usr/libexec/install-tools/bootprofile-apply',
'__INSTALLER_FILE_SWAP_FALLBACK_HELPER__':'/usr/local/libexec/swap-fallback-setup',
'__INSTALLER_FILE_TMPFS_PRE_CLEAN__':'/usr/local/libexec/tmpfs-pre-clean',
'__INSTALLER_FILE_ZRAM_SETUP_HELPER__':'/usr/local/libexec/zram-device-setup',
'__INSTALLER_FILE_ZRAM_WRITEBACK_HELPER__':'/usr/local/libexec/zram-writeback',
}
prefixes=('/usr/local/bin/','/usr/local/sbin/','/usr/local/libexec/','/usr/libexec/install-tools/','/etc/kernel/','/etc/initramfs-tools/','/etc/timeshift/','/pool/')
paths=set(); directives=0
for p in Path('d-i/forky/hooks').rglob('*'):
 if not p.is_file(): continue
 try:t=p.read_text()
 except UnicodeDecodeError:continue
 for line in t.splitlines():
  if not re.match(r'^(ExecStart|ExecStartPre|ExecStartPost|ExecStop|ExecStopPost|ExecReload)=',line):continue
  if line.endswith('='):continue
  directives+=1
  raw=line.split('=',1)[1]
  for ph,dest in placeholders.items():
   if ph in raw: paths.add(dest)
  for token in re.findall(r'(?<![A-Za-z0-9_])(/[A-Za-z0-9_.+@%{}*,:=-]+(?:/[A-Za-z0-9_.+@%{}*,:=-]+)*)',raw):
   if token.startswith(prefixes): paths.add(token.rstrip("'\""))
print(directives,len(paths))
for x in sorted(paths):print(x)
