package LabwcNetworkControlAction::Command;

use strict;
use warnings;

use IPC::Open3 qw(open3);
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Int Str);

has capture_limit_bytes => (
    is      => 'ro',
    isa     => Int,
    default => sub { 1_048_576 },
);

has path => (
    is      => 'ro',
    isa     => Str,
    default => sub { $ENV{PATH} // '/usr/local/bin:/usr/bin:/bin' },
);

sub _status {
    my ($status) = @_;

    return 255 if !defined($status) || $status == -1;
    return 128 + ($status & 127) if $status & 127;
    return $status >> 8;
}

sub executable {
    my ($self, $name) = @_;

    defined($name) && $name =~ /\A[A-Za-z0-9][A-Za-z0-9+._-]*\z/
        or die "invalid executable name\n";
    for my $directory (split /:/, $self->path()) {
        next if $directory !~ m{\A/};
        my $candidate = "$directory/$name";
        return $candidate if -x $candidate && !-d $candidate;
    }
    return undef;
}

sub require_executable {
    my ($self, $name) = @_;

    my $program = $self->executable($name);
    defined($program)
        or die "required network command is not installed: $name\n";
    return $program;
}

sub run {
    my ($self, @argv) = @_;

    @argv && defined($argv[0]) && $argv[0] ne q{}
        or die "cannot run an empty command\n";
    system { $argv[0] } @argv;
    return _status($?);
}

sub run_or_die {
    my ($self, $label, @argv) = @_;

    my $status = $self->run(@argv);
    $status == 0
        or die "$label failed with status $status\n";
    return;
}

sub exec {
    my ($self, @argv) = @_;

    @argv && defined($argv[0]) && $argv[0] ne q{}
        or die "cannot execute an empty command\n";
    CORE::exec { $argv[0] } @argv;
    die "cannot execute $argv[0]: $!\n";
}

sub capture {
    my ($self, %args) = @_;

    my $argv = $args{argv};
    ref($argv) eq 'ARRAY' && @{$argv}
        or die "capture requires a non-empty argv array\n";

    open my $null, '>', '/dev/null' or die "cannot open /dev/null: $!\n";
    my ($stdin, $stdout);
    my $pid = eval { open3($stdin, $stdout, $null, @{$argv}) };
    if ($action eq 'restore-automatic-dns') {
        @args == 2 or die "$action requires a UUID and confirmation\n";
        $args[1] eq 'confirmed-network-action'
            or die "automatic DNS confirmation is missing\n";
        return $self->_restore_automatic_dns($args[0]);
    }
    if ($action eq 'set-custom-dns') {
        @args == 3 or die "$action requires a UUID, DNS list, and confirmation\n";
        $args[2] eq 'confirmed-network-action'
            or die "custom DNS confirmation is missing\n";
        return $self->_set_custom_dns($args[0], $args[1]);
    }
    if ($action eq 'flush-dns-cache') {
        @args == 1 or die "$action requires confirmation\n";
        $args[0] eq 'confirmed-network-action'
            or die "DNS cache flush confirmation is missing\n";
        return $self->_flush_dns_cache();
    }
    if ($action eq 'randomize-macs') {
        @args == 1 or die "$action requires confirmation\n";
        $args[0] eq 'confirmed-network-action'
            or die "managed network randomization confirmation is missing\n";
        return $self->_randomize_physical_adapters();
    }
    die "unsupported privileged network control action: " . (defined($action) ? $action : 'unset') . "\n";
}

sub run {
    my ($self, @argv) = @_;

    return $self->_fatal('privileged network helper must run as root') if $> != 0;
    my $status = eval {
        local $ENV{PATH}   = '/usr/sbin:/usr/bin:/sbin:/bin';
        local $ENV{LC_ALL} = 'C.UTF-8';
        my $invoker_uid = $self->_require_pkexec_invoker();
        @argv or die "usage: labwc-network-control-action-root <action> [argument]\n";
        my $action = shift @argv;
        $self->_dispatch($invoker_uid, $action, @argv);
    };
    return $status if defined($status) && !$@;
    return $self->_fatal($@ || 'privileged network action failed');
}

