sub _source_records_from_status {
    my ($self, $output) = @_;
    my @sources;
    my $in_audio = 0;
    my $in_sources = 0;
    my $order = 0;

    # Forky's WirePlumber supports `wpctl status --name`, but not the newer
    # `wpctl list` interface. Parse only the Audio Sources subtree, excluding
    # output monitors and HDMI/DisplayPort nodes even if WirePlumber has not
    # finished disabling them. Prefer internal ALSA capture over USB or
    # virtual sources; within one tier, retain the current default first.
    for my $line (split /\n/, $output) {
        $line =~ s/\r\z//;
        if (!$in_audio) {
            $in_audio = 1 if $line =~ /\AAudio\s*\z/;
            next;
        }
        if (!$in_sources) {
            last if $line =~ /\A\S/;
            $in_sources = 1 if $line =~ /\bSources:\s*\z/;
            next;
        }

        last if $line =~ /\A\S/;
        last if $line =~ /(?:\x{251c}|\x{2514})\x{2500}\s*[^:]+:\s*\z/;

        my $candidate = $line;
        $candidate =~ s/\A[\s\x{2502}]*//;
        $candidate =~ s/\A(?:\x{251c}|\x{2514})\x{2500}\s*//;
        next if $candidate eq q{};
        my $is_default = $candidate =~ s/\A\*\s*// ? 1 : 0;
        my ($id, $name) = $candidate =~
            /\A([1-9][0-9]*)[.]\s+(.+?)(?:\s+\[[^\]]*\])?\s*\z/;
        next if !defined($id) || !defined($name);
        next if _source_is_blocked($name);
        push @sources, {
            id         => $id,
            name       => $name,
            default    => $is_default,
            preference => _source_preference($name),
            order      => $order++,
        };
    }

    return sort {
        $a->{preference} <=> $b->{preference}
            || $b->{default} <=> $a->{default}
            || $a->{order} <=> $b->{order}
    } @sources;
}

sub _source_ids_from_status {
    my ($self, $output) = @_;
    return map { $_->{id} } $self->_source_records_from_status($output);
}

sub _available_source_ids {
    my ($self, $wpctl) = @_;
    my ($listed, $output) = $self->_command_output_quietly(
        $wpctl, 'status', '--name',
    );
    return if !$listed;

    return $self->_source_ids_from_status($output);
}

sub _wait_for_sources {
    my ($self, $wpctl) = @_;
    my $attempts = $self->default_source_attempts();
    $attempts =~ /\A[1-9][0-9]*\z/ or _fatal('invalid default source attempt count');
    my $retry_seconds = $self->default_source_retry_seconds();
    defined $retry_seconds && $retry_seconds =~ /\A(?:0|[1-9][0-9]*)(?:\.[0-9]+)?\z/
        or _fatal('invalid default source retry interval');

    for my $attempt (1 .. $attempts) {
        my @source_ids = $self->_available_source_ids($wpctl);
        return @source_ids if @source_ids;
        sleep $retry_seconds if $attempt < $attempts;
    }
    return;
}

sub _wait_for_source {
apparmor_apply_desktop_state() {
  mode_config=$1

  [ "${DESKTOP_APPARMOR_STATE+x}" = x ] || return 0
  desktop_apparmor_state=$(apparmor_requested_desktop_state) || return 1
  desktop_apparmor_tmp="${mode_config}.desktop-state.$$"

  awk \
    -v selected_state="$desktop_apparmor_state" '
      /^[[:space:]]*(#|$)/ {
        print
        next
      }
      {
        if (NF != 4) {
          exit 40
        }
        if ($1 !~ /^(enforce|complain|disable)$/ ||
            $2 !~ /^(required|optional|if-executable)$/ ||
            $3 !~ /^[A-Za-z0-9._+-]+$/ ||
            ($2 == "if-executable" && $4 !~ /^\//) ||
            ($2 != "if-executable" && $4 != "-")) {
          exit 41
        }
        if (++seen[$3] != 1) {
          exit 42
        }
        rows++
        $1 = selected_state
        print
      }
      END {
        if (rows == 0) {
          exit 43
        }
      }
    ' "$mode_config" >"$desktop_apparmor_tmp" || {
      rm -f -- "$desktop_apparmor_tmp"
      installer_fatal "failed to apply DESKTOP_APPARMOR_STATE=${desktop_apparmor_state} to every declared managed AppArmor profile"
      return 1
    }

  install -m 0644 "$desktop_apparmor_tmp" "$mode_config" || {
    rm -f -- "$desktop_apparmor_tmp"
    installer_fatal "failed to publish desktop AppArmor mode policy: ${mode_config}"
    return 1
  }
  rm -f -- "$desktop_apparmor_tmp"
  installer_info "all declared managed AppArmor profile state: ${desktop_apparmor_state}"
}

security_nvidia_acceleration_enabled() {
  nvidia_addon_selected=${NVIDIA_ADDON_SELECTED:-false}
  nvidia_gpu_detected=${NVIDIA_GPU_DETECTED:-false}

  case "$nvidia_addon_selected" in
    true|false) ;;
    *)
      installer_fatal "NVIDIA_ADDON_SELECTED must be true or false, got: ${nvidia_addon_selected}"
      return 1
      ;;
  esac
  case "$nvidia_gpu_detected" in
    true|false) ;;
    *)
      installer_fatal "NVIDIA_GPU_DETECTED must be true or false, got: ${nvidia_gpu_detected}"
        vivaldi          => [qw(vivaldi-stable vivaldi-bin)],
        zoom             => [qw(usr.bin.zoom)],
    );
    exists $profiles{$application}
        or die "unsupported managed AppArmor application: $application\n";
    return @{ $profiles{$application} };
}

sub _desktop_profiles {
    my ($self) = @_;

    # The global state owns every declared managed profile source. Individual
    # application actions remain limited to their application-specific rows.
    return map { $_->[2] } $self->_mode_rows();
}

sub _mode_rows {
    my ($self) = @_;

    $self->_validate_mode_config();
    my $content = $self->_read_small_file($self->mode_config(), $self->maximum_config_bytes(), 'managed AppArmor mode configuration');
    my @rows;
    for my $line (split /\n/, $content) {
        next if $line =~ /^\s*(?:#|\z)/;
        my @fields = split /\s+/, $line;
        @fields == 4
            or die "managed AppArmor mode configuration is malformed\n";
        push @rows, \@fields;
    }
    return @rows;
}

sub print_application_modes {
    my ($self) = @_;

