    no strict 'refs';
    *{"${caller}::has"} = sub {
        my ($name, @arguments) = @_;
        my %specification = @arguments;
        $attributes{$name} = \%specification;
        *{"${caller}::${name}"} = sub { return $_[0]->{$name}; };
        return;
    };
    *{"${caller}::new"} = sub {
        my ($package, @arguments) = @_;
