sub extract_manifest {
    my ($text, $function) = @_;
    $text =~
      /^\Q$function\E[(][)][ \t]*[{][ \t]*\n[ \t]*cat[ \t]+<<['"]?EOF['"]?[ \t]*\n(.*?)^EOF[ \t]*$/ms
      or die "cannot parse $function manifest";
    return grep { $_ ne q{} } map {
        my $line = $_;
        $line =~ s/\A\s+//;
        $line =~ s/\s+\z//;
        $line;
    } split /\n/, $1;
}

