}

sub invalid_config_exits_nonzero {
    my ($config_path) = @_;
    open my $saved_stderr, '>&', \*STDERR or die "dup STDERR: $!";
    open STDERR, '>', File::Spec->devnull or die "redirect STDERR: $!";
