        '-I',
        $lib,
        '-MZram::Config=load_config',
        '-e',
        'load_config($ARGV[0])',
        $config_path,
    );
    open STDERR, '>&', $saved_stderr or die "restore STDERR: $!";
    return $? != 0 ? 1 : 0;
}

