    30	            !-l $disable_link &&
    31	            _file_has_match(
    32	                $profile_path,
    33	                qr/flags=\([^)]*complain(?:[[:space:],)]|\z)/,
    34	            ) &&
    35	            !_file_has_match(
    36	                $profile_path,
    37	                qr/flags=\([^)]*audit(?:[[:space:],)]|\z)/,
    38	            );
    39	    }
    40	    if ($mode eq 'enforce') {
    41	        return !-e $disable_link &&
    42	            !-l $disable_link &&
    43	            !_file_has_match(
    44	                $profile_path,
    45	                qr/flags=\([^)]*(?:audit|complain|default_allow|unconfined)/,
    46	            );
    47	    }
    48	    if ($mode eq 'disable') {
    49	        return -l $disable_link &&
    50	            defined(readlink($disable_link)) &&
    51	            readlink($disable_link) eq $profile_path;
    52	    }
    53	    return 0;
    54	}
