    38	        $limits->{max_config_bytes},
    39	    );
    40	
    41	    my $content = read_bounded_file(
    42	        'mode configuration',
    43	        $options->{config_path},
    44	        $limits->{max_config_bytes},
    45	    );
    46	    my @lines = length($content) ? split(/\n/, $content, -1) : ();
    47	    pop @lines if @lines && $content =~ /\n\z/;
    48	
    49	    my @entries;
    50	    my %seen_profiles;
    51	    my $line_number = 0;
    52	
    53	    for my $line (@lines) {
    54	        ++$line_number;
    55	        length($line) <= $limits->{max_line_bytes} ||
    56	            fatal(
    57	                "configuration line $line_number exceeds "
    58	                . "$limits->{max_line_bytes} bytes"
    59	            );
    60	        next if $line eq '' || $line =~ /\A#/;
    61	
    62	        $line =~ /\A[A-Za-z0-9._\/\@%:+,\-]+(?: +[A-Za-z0-9._\/\@%:+,\-]+){3}\z/ ||
    63	            fatal(
    64	                "configuration line $line_number contains unsupported "
    65	                . 'characters or spacing'
    66	            );
    67	
    68	        my @fields = split(/ +/, $line, -1);
    69	        @fields == 4 ||
    70	            fatal(
    71	                "configuration line $line_number must contain exactly four fields"
    72	            );
