    74	        my ($mode, $presence, $profile_name, $executable_probe) = @fields;
    75	        $mode =~ /\A(?:enforce|complain|disable)\z/ ||
    76	            fatal(
    77	                "configuration line $line_number has an invalid mode: $mode"
    78	            );
    79	        $presence =~ /\A(?:required|optional|if-executable)\z/ ||
    80	            fatal(
    81	                "configuration line $line_number has an invalid presence policy: "
    82	                . $presence
    83	            );
    84	        $profile_name =~ /\A[A-Za-z0-9._+\-]+\z/ ||
    85	            fatal(
    86	                "configuration line $line_number has an invalid profile file: "
    87	                . $profile_name
    88	            );
    89	        !$seen_profiles{$profile_name}++ ||
    90	            fatal(
    91	                "configuration line $line_number repeats profile file: "
    92	                . $profile_name
    93	            );
    94	
    95	        if ($presence eq 'if-executable') {
    96	            validate_absolute_path(
    97	                'configuration executable probe',
    98	                $executable_probe,
    99	            );
   100	        }
   101	        else {
   102	            $executable_probe eq '-' ||
   103	                fatal(
   104	                    "configuration line $line_number must use '-' "
   105	                    . 'as its executable probe'
   106	                );
   107	        }
   108	
   109	        if ($presence eq 'if-executable' && !-x $executable_probe) {
   110	            info(
   111	                "skipping profile $profile_name; executable is absent: "
   112	                . $executable_probe
   113	            );
