   117	        my $profile_path = "$options->{profile_dir}/$profile_name";
   118	        if (!-e $profile_path) {
   119	            if ($presence eq 'required') {
   120	                fatal("required AppArmor profile is missing: $profile_name");
   121	            }
   122	            if ($presence eq 'if-executable') {
   123	                warn(
   124	                    'installed executable has no package AppArmor profile; '
   125	                    . "skipping mode management: $executable_probe -> "
   126	                    . $profile_name
