   135	        validate_root_owned_file(
   136	            'AppArmor profile',
   137	            $profile_path,
   138	            $limits->{max_profile_bytes},
   139	        );
   140	        push @entries, {
   141	            mode     => $mode,
   142	            name     => $profile_name,
   143	            path     => $profile_path,
   144	            presence => $presence,
   145	        };
   146	    }
   147	
   148	    return \@entries;
